<?php
declare(strict_types=1);

return static function (PDO $pdo): void {
    $authors = ['Анна Смирнова', 'Максим Орлов', 'Редакция Вебпрактики'];
    $ids = [];
    foreach ($authors as $index => $name) {
        $query = $pdo->prepare('INSERT INTO users (name, email, password) VALUES (?, ?, ?)');
        $query->execute([$name, 'author' . $index . '@example.test', password_hash(bin2hex(random_bytes(24)), PASSWORD_DEFAULT)]);
        $ids[] = (int) $pdo->lastInsertId();
    }
    $materials = [
        ['Как браузер разговаривает с сервером', 'web', 7, 15, 'Разбираем путь запроса: от адресной строки до HTML-ответа. В конце проверим всё на практике.',
            "Когда вы открываете страницу, браузер отправляет HTTP-запрос. В нём есть метод, путь и заголовки. Метод GET обычно получает данные, а POST передаёт введённую информацию серверу.\n\nСервер разбирает запрос и выбирает обработчик. PHP может прочитать параметры, обратиться к базе данных и собрать HTML. В ответе браузер получает статус, заголовки и тело документа.\n\nСтатус 200 означает успешный запрос, 404 — отсутствие страницы. После отправки формы сервер часто возвращает перенаправление 303: следующий запрос будет GET. Это помогает избежать повторной отправки формы при обновлении страницы.\n\nПрактика. Откройте инструменты разработчика, вкладку «Сеть», затем обновите страницу. Найдите запрос документа и сравните его метод, статус и Content-Type с запросом файла стилей."],
        ['Первая форма: GET, POST и проверка данных', 'php', 8, 20, 'Собираем понятную форму и учимся проверять данные на сервере, даже если браузер уже сделал свою проверку.',
            "Форма связывает поля ввода с запросом. Атрибут name определяет имя параметра, method — метод отправки, action — адрес обработчика. Поиск удобно передавать через GET, чтобы результат можно было сохранить в закладках.\n\nДанные из формы нельзя считать правильными заранее. Проверяйте тип значения, длину строки и допустимый диапазон чисел. Клиентские required и minlength полезны для удобства, но их можно обойти.\n\nПосле ошибки сохраните безопасные введённые значения и покажите конкретное пояснение. Пароль обратно в HTML возвращать не следует. При успешной записи используйте перенаправление на страницу результата.\n\nПрактика. Отправьте форму обратной связи с коротким сообщением. Сравните реакцию браузера с серверной проверкой. Затем отправьте корректные данные и убедитесь, что показано сообщение об успешном сохранении."],
        ['Маршруты и контроллеры без магии', 'php', 9, 25, 'Отделяем адрес страницы от её реализации и передаём параметры URL в методы контроллера.',
            "Фронт-контроллер — единая точка входа приложения. Он подключает окружение и передаёт запрос роутеру. Таблица маршрутов связывает HTTP-метод и путь с конкретным действием контроллера.\n\nПуть /articles/3 содержит идентификатор статьи. Роутер проверяет формат адреса и передаёт число в метод show(). Контроллер получает модель, проверяет результат и выбирает представление.\n\nОтсутствующая статья должна возвращать 404. Существующий путь с неподходящим методом — 405. Такие ответы важны и для человека, и для программ, которые обращаются к сайту.\n\nПрактика. Откройте любую статью и измените число в адресе на несуществующее. Затем найдите маршрут /articles/{id} в routes.php и проследите вызов до шаблона страницы."],
        ['Шаблоны, которые удобно поддерживать', 'web', 6, 15, 'Общий каркас страницы, отдельные представления и безопасный вывод пользовательского текста.',
            "На разных страницах повторяются шапка, навигация и подвал. Если вынести их в общий шаблон, изменение меню потребует одной правки. Конкретная страница передаёт в этот каркас свой заголовок и содержимое.\n\nПредставление отвечает за HTML, а не за SQL-запросы. Контроллер заранее получает нужные данные и передаёт их шаблону. Это делает код понятнее и упрощает поиск ошибок.\n\nЛюбой пользовательский текст необходимо экранировать перед вставкой в HTML. Функция htmlspecialchars превращает специальные символы в безопасное представление. Сам факт проверки длины строки от XSS не защищает.\n\nПрактика. Найдите общий layout.php и сравните его с шаблоном статьи. Обратите внимание на title и функцию e(), которая используется при выводе названий и комментариев."],
        ['SQLite: таблицы, связи и первый запрос', 'database', 10, 30, 'Проектируем небольшую базу для статей и авторов. Разбираемся с ключами и подготовленными запросами.',
            "SQLite хранит базу в одном файле и подходит для небольшого учебного проекта. Таблица описывает однотипные записи, столбцы — их свойства. Первичный ключ однозначно определяет каждую строку.\n\nВместо копирования имени автора в каждую статью храните author_id. Внешний ключ связывает его с users.id. При изменении имени пользователя все статьи продолжат ссылаться на ту же запись.\n\nЗначения из запроса передавайте через параметры подготовленного выражения PDO. Имена таблиц и столбцов выбирайте только из заранее известных значений: параметры SQL не заменяют идентификаторы.\n\nПрактика. Создайте свой материал и найдите его в личном кабинете. В коде модели посмотрите, как INSERT получает значения отдельно от SQL и как lastInsertId возвращает идентификатор."],
        ['Active Record: модель умеет сохраняться', 'database', 9, 25, 'Связываем объект PHP с записью в таблице и оставляем SQL внутри слоя работы с данными.',
            "В шаблоне Active Record объект соответствует строке таблицы. Его свойства представляют значения полей, а методы save() и delete() управляют этой записью. Общую механику можно вынести в базовый класс.\n\nКласс Article задаёт имя таблицы и список разрешённых полей. Такой список ограничивает массовое присваивание: приложение не должно принимать от пользователя любое имя столбца. author_id назначает контроллер после проверки входа.\n\nБаза данных создаётся через один объект соединения. Singleton в этом проекте обеспечивает повторное использование PDO в пределах запроса, а не создаёт новое подключение для каждой модели.\n\nПрактика. Найдите ActiveRecord.php и метод save(). Сравните ветки INSERT и UPDATE. Затем измените заголовок своей статьи и убедитесь, что её идентификатор остался прежним."],
        ['Сессии и вход в личный кабинет', 'php', 8, 20, 'Как сервер узнаёт пользователя между запросами и почему пароль нельзя хранить открытым текстом.',
            "HTTP-запросы независимы. Сессия позволяет сохранить на сервере идентификатор вошедшего пользователя, а браузер отправляет только cookie с идентификатором сессии. Пароль в этой cookie не нужен.\n\nПароль хранится в виде стойкого хеша, созданного password_hash(). Для проверки используется password_verify(). После успешного входа идентификатор сессии обновляется, что снижает риск фиксации сессии.\n\nПроверка прав выполняется для каждого изменения. Даже если ссылка редактирования не показана, пользователь может самостоятельно набрать URL. Поэтому контроллер сравнивает author_id с идентификатором текущего пользователя.\n\nПрактика. Зарегистрируйтесь, опубликуйте материал, выйдите из аккаунта и попробуйте открыть его редактирование по сохранённому адресу. Приложение должно предложить войти."],
        ['Комментарии: от формы до записи в базе', 'web', 7, 25, 'Добавляем обсуждение к статье, связываем комментарий с пользователем и возвращаемся к нему по якорю.',
            "У комментария есть свой идентификатор, автор, статья, текст и дата публикации. Отдельная таблица comments позволяет хранить сколько угодно комментариев без изменения структуры articles.\n\nФорма под статьёй отправляет POST на /articles/123/comments. Сервер проверяет вход, CSRF-токен, существование статьи и длину текста. Автор берётся из сессии, а не из скрытого поля формы.\n\nПосле сохранения выполняется перенаправление на /articles/123#comment456. Якорь помогает сразу найти новый комментарий. Для редактирования используется отдельный адрес /comments/456/edit с повторной проверкой прав.\n\nПрактика. Оставьте комментарий под этой статьёй, измените его и посмотрите на адрес страницы. Затем проверьте, что ссылки изменения появляются только возле ваших сообщений."],
    ];
    $dates = ['2026-11-15 09:30:00', '2026-11-15 16:10:00', '2026-11-16 12:00:00', '2026-11-17 10:20:00', '2026-11-18 09:15:00', '2026-11-18 18:40:00', '2026-11-19 14:30:00', '2026-11-20 08:00:00'];
    $query = $pdo->prepare('INSERT INTO articles (author_id, title, category, read_minutes, practice_minutes, summary, body, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)');
    foreach ($materials as $index => $material) {
        [$title, $category, $read, $practice, $summary, $body] = $material;
        $query->execute([$ids[$index % 3], $title, $category, $read, $practice, $summary, $body, $dates[$index], $dates[$index]]);
    }
    $query = $pdo->prepare('INSERT INTO comments (author_id, article_id, body) VALUES (?, ?, ?)');
    $query->execute([$ids[0], 8, 'Полезно после отправки формы посмотреть статус 303 во вкладке «Сеть». Так видно, как работает перенаправление.']);
    $query->execute([$ids[1], 8, 'Для самостоятельной проверки попробуйте отправить пустой комментарий: сервер должен вернуть ошибку и сохранить введённый текст.']);
};
